#!/usr/bin/env python3
"""Build the shipping skin from reviewed design PNGs; never renders or edits design inputs.

Python 3 + Pillow. Run: python3 -I scripts/deck-assets/build.py [--check]
--check compares every generated byte without writing; --out DIR builds a private comparison pack.
Masks deliberately reproduce docs/deck-design/tools/compose.py, including its 4x Lanczos edge.
"""
import argparse
import hashlib
import io
import json
from pathlib import Path
import platform
import sys

from PIL import Image, ImageDraw, __version__ as pillow_version

ROOT = Path(__file__).resolve().parents[2]
SOURCE = ROOT / 'docs/deck-design'
DEFAULT_OUT = ROOT / 'apps/mobile/assets/deck'
MASKS = {
    'agent': ('rrect', 358, 340, 60),
    'cmd': ('rrect', 358, 280, 54),
    'ptt': ('rrect', 340, 352, 72),
    'stick': ('circle', 322, 322, 0),
    'dial': ('circle', 322, 322, 0),
}
EXPECTED = {'agent': (372, 355), 'cmd': (372, 294), 'ptt': (355, 366),
            'stick': (337, 336), 'dial': (337, 336)}
EXPECTED_NAMES = ([f'agent_{tone}_{state}' for tone in ('amber', 'violet', 'blue', 'green', 'red', 'gray', 'off')
                   for state in ('up', 'pressed', 'selected')] + ['cmd_up', 'cmd_pressed', 'ptt_up', 'ptt_pressed',
                   'ptt_active', 'stick_center', 'stick_left', 'stick_right', 'stick_up', 'stick_down', 'dial'])


def sha(data):
    return hashlib.sha256(data).hexdigest()


def read(relative):
    return (SOURCE / relative).read_bytes()


def mask_for(family, size):
    shape, w, h, radius = MASKS[family]
    ss = 4
    mask = Image.new('L', (size[0] * ss, size[1] * ss), 0)
    draw = ImageDraw.Draw(mask)
    cx, cy = size[0] * ss / 2, size[1] * ss / 2
    box = (cx - w * ss / 2, cy - h * ss / 2, cx + w * ss / 2, cy + h * ss / 2)
    if shape == 'circle':
        draw.ellipse(box, fill=255)
    else:
        draw.rounded_rectangle(box, radius=radius * ss, fill=255)
    return mask.resize(size, Image.Resampling.LANCZOS)


def placement(x, y, family):
    # Exact compose.py center rounding, followed by integer half-crop placement.
    w, h = EXPECTED[family]
    cx, cy = round((x + 1.95) * 300), round((4.22 - y) * 300)
    return dict(x=cx - w // 2, y=cy - h // 2, w=w, h=h)


def build():
    source_manifest = read('renders/sprites_raw/manifest.json')
    original = json.loads(source_manifest)
    assert original['pxPerPt'] == 3 and original['basePt'] == {'w': 390, 'h': 844}
    assert list(original['sprites']) == EXPECTED_NAMES, 'Expected exactly the reviewed 32 named sprites'
    files = {'base.png': read('renders/base.png')}
    with Image.open(io.BytesIO(files['base.png'])) as base:
        assert base.size == (1170, 2532)
        assert base.convert('RGBA').getchannel('A').getextrema() == (255, 255)
    manifest = dict(original)
    manifest.update(format=1, source='docs/deck-design', alphaBaked=True,
                    base={'file': 'base.png', 'px': {'w': 1170, 'h': 2532},
                          'sourceSha256': sha(files['base.png']), 'sha256': sha(files['base.png']),
                          'bytes': len(files['base.png'])},
                    sourceManifestSha256=sha(source_manifest),
                    sourceComposeSha256=sha(read('tools/compose.py')),
                    sourceBlenderScriptSha256=sha(read('blender/deck_scene.py')),
                    generator={'file': 'scripts/deck-assets/build.py', 'sha256': sha(Path(__file__).read_bytes()),
                               'python': platform.python_version(), 'pillow': pillow_version})
    sprites = {}
    for name, source_entry in original['sprites'].items():
        family = name.split('_')[0]
        raw = read('renders/sprites_raw/' + source_entry['file'])
        image = Image.open(io.BytesIO(raw)).convert('RGBA')
        px = source_entry['px']
        assert image.size == EXPECTED[family] == (px['w'], px['h']), name
        for field in ('x', 'y', 'w', 'h'):
            assert abs(source_entry[field] * 3 - px[field]) < 1e-9, (name, field)
        assert 0 <= px['x'] < px['x'] + px['w'] <= 1170
        assert 0 <= px['y'] < px['y'] + px['h'] <= 2532
        assert image.getchannel('A').getextrema() == (255, 255), 'Reviewed source crops must be opaque'
        mask = mask_for(family, image.size)
        assert mask.getextrema() == (0, 255)
        assert all(mask.getpixel(corner) == 0 for corner in ((0, 0), (image.width-1, 0),
                   (0, image.height-1), (image.width-1, image.height-1)))
        image.putalpha(mask)
        output = io.BytesIO()
        image.save(output, format='PNG', optimize=True)
        payload = output.getvalue()
        files['sprites/' + source_entry['file']] = payload
        shape, w, h, radius = MASKS[family]
        sprites[name] = dict(source_entry, file='sprites/' + source_entry['file'],
                             sourceFile='renders/sprites_raw/' + source_entry['file'],
                             sourceSha256=sha(raw), sha256=sha(payload), bytes=len(payload),
                             # Source radiusPx is retained above; bakedMask is the actual shipping alpha.
                             bakedMask={'shape': shape, 'w': w, 'h': h, 'radiusPx': radius, 'supersample': 4})
    manifest['sprites'] = sprites
    manifest['placementsPx'] = {
        'agentSlots': [placement(x, y, 'agent') for y in (1.68, .48) for x in (-1.2267, 0, 1.2267)],
        'cmdSlots': [placement(x, y, 'cmd') for y in (-.94, -1.94) for x in (-1.2267, 0, 1.2267)],
        'ptt': placement(0, -3.20, 'ptt'), 'stick': placement(-1.25, -3.20, 'stick'),
        'dial': placement(1.25, -3.20, 'dial'),
    }
    for group in manifest['placementsPx'].values():
        for rect in group if isinstance(group, list) else [group]:
            assert 0 <= rect['x'] < rect['x'] + rect['w'] <= 1170
            assert 0 <= rect['y'] < rect['y'] + rect['h'] <= 2532
    files['manifest.json'] = (json.dumps(manifest, indent=2) + '\n').encode()
    return files


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    parser.add_argument('--out', type=Path, default=DEFAULT_OUT)
    args = parser.parse_args()
    files = build()
    for name, payload in files.items():
        dest = args.out / name
        if args.check:
            assert dest.read_bytes() == payload, f'Stale shipping asset: {dest}'
        else:
            dest.parent.mkdir(parents=True, exist_ok=True)
            dest.write_bytes(payload)
    print(json.dumps({'mode': 'checked' if args.check else 'built', 'files': len(files),
                      'sprites': 32, 'pngBytes': sum(len(v) for k, v in files.items() if k.endswith('.png')),
                      'out': str(args.out)}))


if __name__ == '__main__':
    main()
